#!/usr/bin/env python3
"""Make the private comparison and discussion page."""
import importlib.util
from pathlib import Path
spec=importlib.util.spec_from_file_location("editorial",Path(__file__).with_name("build-editorial.py"))
e=importlib.util.module_from_spec(spec);spec.loader.exec_module(e)
modules=[
("home","01","A homepage centered on the research","/","An opening about the questions behind the work, direct and prominent access to the papers, then selected manuscripts and research programs. Essays and visual companions follow.","Does the opening have the right intellectual depth? Are the papers unmistakably central?"),
("gallery","02","A visual explorer gallery","/explorers/","All four existing explorers, introduced through a question and a diagram. Their calculations and interactions are preserved.","Do the questions make you want to enter? Should the order or artwork change?"),
("research","03","Guides to the research","/research/","Six program guides covering all 39 papers, with reading routes, scope notes, and expandable abstracts.","Are these useful groupings and entry points? We can keep individual guides independently."),
("papers","04","A searchable paper catalogue","/papers/","Subject navigation, keyword search, compact view, and larger descriptions. Existing paper entries, PDF links, and archive links remain.","Does the catalogue remain comfortable to browse? Try a title, subject, and compact view."),
("writing","05","A series of interactive essays","/writing/","Two complete new essay drafts alongside Not Enough and Gradient of Mind. Both new experiments use explicit illustrative assumptions.","Review the institutional-knowledge and physical-limits essays separately: argument, tone, calculation, and visual experience."),
("about","06","About, updates, and RSS","/about/","The fuller introduction has a home on About; contact uses your existing LinkedIn. Updates and RSS contain verified existing releases.","How much personal context belongs here? Is LinkedIn the right contact route? What deserves an update?")
]
body='''<header class="page-intro"><p class="kicker">Private design review · 25 October 2026</p><h1>A complete proposal.<br>Every part is discussable.</h1><p class="intro">This is a local working version. Nothing here has been pushed or published. Open the proposed site, compare it with the current version, and keep, revise, or leave out any of the six changes.</p><div class="entry-links"><a class="button" href="/">Explore the new homepage ↗</a><a class="button secondary" href="http://127.0.0.1:8765/" target="_blank" rel="noopener">Open the current site ↗</a></div></header><p class="small">Review notes stay in this browser. They are not sent anywhere, and choosing “Keep” does not publish anything. Export notes if you want a separate copy.</p><form id="review-form">'''
for key,n,title,url,desc,prompt in modules:
 body+=f'''<section class="review-card"><p class="kicker">Proposal {n}</p><h2><a href="{url}">{title} ↗</a></h2><p>{desc}</p><p class="small">{prompt}</p><label for="decision-{key}">Decision <select id="decision-{key}" name="{key}-decision"><option>Undecided</option><option>Keep</option><option>Revise</option><option>Leave out</option></select></label><label for="notes-{key}">Notes</label><textarea id="notes-{key}" name="{key}-notes" placeholder="What works? What should change?"></textarea></section>'''
body+='''</form><div class="entry-links"><button id="export-notes">Export review notes</button><span id="save-status" class="small" role="status">Notes save as you type.</span></div><aside class="guide-aside"><p class="small">The two new essays are drafts for discussion. New illustrations are schematic; their captions and the experiments state what is being represented. Manuscript PDFs and bibliographic records are unchanged. The shared navigation and stylesheet are common dependencies when adopting selected pages.</p></aside><p><a href="/writing/institutional-knowledge/">Institutional knowledge ↗</a> · <a href="/writing/physical-limits/">Physical limits ↗</a> · <a href="/updates/">Updates ↗</a> · <a href="/feed.xml">RSS feed ↗</a></p>'''
e.page("review/index.html","Review the website proposal","Local comparison and discussion of six proposed website improvements.",body,extra='<meta name="robots" content="noindex,nofollow"><script defer src="/assets/review.js"></script>')
